#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long differenceLimit;
    cin >> n >> differenceLimit;
    vector<pair<long long, long long>> friends(n);
    for (auto &person : friends) cin >> person.first >> person.second;
    sort(friends.begin(), friends.end());
    int left = 0;
    long long windowSum = 0, bestSum = 0;
    for (int right = 0; right < n; ++right) {
        windowSum += friends[right].second;
        while (friends[right].first - friends[left].first >= differenceLimit) {
            windowSum -= friends[left].second;
            ++left;
        }
        bestSum = max(bestSum, windowSum);
    }
    cout << bestSum << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> children(n);
    queue<pair<int, int>> pending;
    for (int employee = 0; employee < n; ++employee) {
        int manager;
        cin >> manager;
        if (manager == -1) pending.push({employee, 1});
        else children[manager - 1].push_back(employee);
    }
    int groups = 0;
    while (!pending.empty()) {
        auto [employee, depth] = pending.front();
        pending.pop();
        groups = max(groups, depth);
        for (int child : children[employee]) pending.push({child, depth + 1});
    }
    cout << groups << '\n';
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int start, target;
    cin >> start >> target;
    if (start >= target) {
        cout << start - target << '\n';
        return 0;
    }
    vector<int> distance(2 * target + 1, -1);
    queue<int> pending;
    distance[start] = 0;
    pending.push(start);
    while (!pending.empty()) {
        int value = pending.front();
        pending.pop();
        if (value == target) break;
        for (int next : {value - 1, value * 2}) {
            if (next < 1 || next > 2 * target || distance[next] != -1) continue;
            distance[next] = distance[value] + 1;
            pending.push(next);
        }
    }
    cout << distance[target] << '\n';
}
